def caesar_shift(s, k):
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shift = ord('a') + k
            result.append(chr((ord(ch) - shift) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            shift = ord('A') + k
            result.append(chr((ord(ch) - shift) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)
