def caesar_shift(s, k):
    result = []
    for ch in s:
        if ch.isalpha():
            shift = ord('a') + k if ch.islower() else ord('A') + k
            result.append(chr((ord(ch) - shift) % 26 + (ord('a') if ch.islower() else ord('A'))))
        else:
            result.append(ch)
    return ''.join(result)
